create extension if not exists "pgcrypto";
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text not null default 'Artist',role text not null default 'user' check(role in('user','artist','admin')),bio text,avatar_url text,created_at timestamptz not null default now());
create table if not exists public.artworks(id uuid primary key default gen_random_uuid(),artist_id uuid not null references public.profiles(id) on delete cascade,title text not null check(char_length(title) between 2 and 120),description text not null default '',price numeric(12,2) not null check(price>=0),category text not null,image_url text not null,status text not null default 'published' check(status in('draft','published','archived')),featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists artworks_artist_idx on public.artworks(artist_id);create index if not exists artworks_category_idx on public.artworks(category);create index if not exists artworks_status_idx on public.artworks(status);create index if not exists artworks_created_idx on public.artworks(created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,email,full_name,role) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name','User'),case when new.raw_user_meta_data->>'role' in('artist','user') then new.raw_user_meta_data->>'role' else 'user' end);return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end;$$;drop trigger if exists artworks_touch on public.artworks;create trigger artworks_touch before update on public.artworks for each row execute procedure public.touch_updated_at();
alter table public.profiles enable row level security;alter table public.artworks enable row level security;
drop policy if exists "profiles public read" on public.profiles;create policy "profiles public read" on public.profiles for select using(true);
drop policy if exists "profile self update" on public.profiles;create policy "profile self update" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "artworks public read" on public.artworks;create policy "artworks public read" on public.artworks for select using(status='published' or artist_id=auth.uid());
drop policy if exists "artist own insert" on public.artworks;create policy "artist own insert" on public.artworks for insert with check(artist_id=auth.uid() and exists(select 1 from public.profiles where id=auth.uid() and role='artist'));
drop policy if exists "artist own update" on public.artworks;create policy "artist own update" on public.artworks for update using(artist_id=auth.uid()) with check(artist_id=auth.uid());
drop policy if exists "artist own delete" on public.artworks;create policy "artist own delete" on public.artworks for delete using(artist_id=auth.uid());
insert into storage.buckets(id,name,public) values('artworks','artworks',true) on conflict(id) do update set public=true;
drop policy if exists "artwork images public read" on storage.objects;create policy "artwork images public read" on storage.objects for select using(bucket_id='artworks');
drop policy if exists "artist image upload" on storage.objects;create policy "artist image upload" on storage.objects for insert to authenticated with check(bucket_id='artworks' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "artist image delete" on storage.objects;create policy "artist image delete" on storage.objects for delete to authenticated using(bucket_id='artworks' and (storage.foldername(name))[1]=auth.uid()::text);
